WITH lines AS (SELECT id, service, host, log_ts, latency_ms, attr_key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS attr_key, attr_value) SELECT host, attr_value, COUNT(latency_ms) OVER (PARTITION BY DATE_TRUNC('WEEK', log_ts), attr_key) AS log_ts_period_count_latency_ms, COUNT(latency_ms) OVER w_hist AS latency_ms_count_30m, MAX(latency_ms) OVER (PARTITION BY attr_key, service ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) AS latency_ms_max_30m FROM lines WINDOW w_hist AS (PARTITION BY attr_key ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW);
